From facd2ee2b6e6a7be7182bbf734ba26bd94ee3083 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 11:09:22 +0100
Subject: [PATCH] applets/taskmanager: don't jump task buttons when new tasks
 appear on the left

With new tasks on the left, the layout is mirrored and grows towards the
left, so every button's x changes when a task is added even though it
stays in place on screen. Track its distance from the right edge instead.

BUG: 499270
---
 applets/taskmanager/qml/Task.qml | 9 ++++++---
 1 file changed, 6 insertions(+), 3 deletions(-)

diff --git a/applets/taskmanager/qml/Task.qml b/applets/taskmanager/qml/Task.qml
index 90530078c5..ea6ce881d8 100644
--- a/applets/taskmanager/qml/Task.qml
+++ b/applets/taskmanager/qml/Task.qml
@@ -89,13 +89,16 @@ PlasmaCore.ToolTipArea {
         if (!completed) {
             return;
         }
+        // A mirrored layout grows to the left, so track the distance from its right edge instead
+        const mirrored = !inPopup && task.parent.LayoutMirroring.enabled;
+        const newX = mirrored ? task.parent.width - x : x;
         if (oldX < 0) {
-            oldX = x;
+            oldX = newX;
             return;
         }
-        moveAnim.x = oldX - x + translateTransform.x;
+        moveAnim.x = (mirrored ? newX - oldX : oldX - newX) + translateTransform.x;
         moveAnim.y = translateTransform.y;
-        oldX = x;
+        oldX = newX;
         moveAnim.restart();
     }
     onYChanged: {
-- 
